def fill4(g):
    g=g.copy(); Hh,Ww=g.shape; used=np.zeros_like(g,bool)
    for r in range(Hh):
        for c in range(Ww):
            if used[r,c]: continue
            v=g[r,c]; w=0
            while c+w<Ww and g[r,c+w]==v: w+=1
            if w<3: continue
            h=1
            while r+h<Hh and all(g[r+h,c+k]==v for k in range(w)): h+=1
            if h>=3 and w>=3:
                g[r:r+h,c:c+w]=4; used[r:r+h,c:c+w]=True
