def rects_geo(G):
    res=[]
    for r0 in range(G.shape[0]):
        for c0 in range(G.shape[1]):
            v=G[r0,c0]
            h=1
            while r0+h<G.shape[0] and G[r0+h,c0]==v: h+=1
            w=1
            while c0+w<G.shape[1] and all(G[r0+r,c0+w]==v for r in range(h)): w+=1
            # maximal rect anchored greedily: actually enumerate all geometric rects from this cell
            for hh in range(3,h+1):
                for ww in range(3,w+1):
                    for a in range(h-hh+1):
                        for b in range(w-ww+1):
                            res.append((r0+a,c0+b,hh,ww))
    return set(res)
def comps(G):
    seen=np.zeros_like(G,bool); out=[]
    for r0 in range(G.shape[0]):
        for c0 in range(G.shape[1]):
            if seen[r0,c0]: continue
            v=G[r0,c0]; st=[(r0,c0)]; cells=[]; seen[r0,c0]=True
            while st:
                r,c=st.pop(); cells.append((r,c))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    rr,cc=r+dr,c+dc
                    if 0<=rr<G.shape[0] and 0<=cc<G.shape[1] and not seen[rr,cc] and G[rr,cc]==v:
                        seen[rr,cc]=True; st.append((rr,cc))
            out.append((v,cells))
    return out
def rule2(G, fillv=4):
    R=rects_geo(G); O=G.copy()
    for v,cells in comps(G):
        rs=[b for b in R if G[b[0],b[1]]==v]
        if not rs: continue
        for (r,c) in cells:
            if any(b[0]<=r<b[0]+b[2] and b[1]<=c<b[1]+b[3] for b in rs):
                O[r,c]=fillv
    return O
